def setZeroes(matrix):
    if not matrix:
        return
    m, n = len(matrix), len(matrix[0])

    # Flags to determine if first row or first column should be zeroed
    first_row_zero = any(matrix[0][j] == 0 for j in range(n))
    first_col_zero = any(matrix[i][0] == 0 for i in range(m))

    # Use first row and first column as markers for zero-rows and zero-columns
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][j] == 0:
                matrix[i][0] = 0
                matrix[0][j] = 0

    # Zero out cells except first row and first column based on markers
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0

    # Zero first row if needed
    if first_row_zero:
        for j in range(n):
            matrix[0][j] = 0

    # Zero first column if needed
    if first_col_zero:
        for i in range(m):
            matrix[i][0] = 0
